/* Page sections. Each block is used by the page named in its comment. */

/* Home */

.hero {
  position: relative;
  overflow: hidden;
  padding: var(--space-8) 0 calc(var(--space-8) + 56px);
  border-bottom: 1px solid var(--color-line);
  background: linear-gradient(180deg, var(--color-brand-tint), var(--color-bg));
}

.hero::before {
  content: '';
  position: absolute;
  top: -140px;
  right: -100px;
  width: 460px;
  height: 460px;
  border-radius: 50%;
  background: radial-gradient(closest-side, rgba(6, 182, 212, 0.2), rgba(6, 182, 212, 0));
}

.hero-inner {
  position: relative;
  display: grid;
  grid-template-columns: 1fr 420px;
  gap: var(--space-7);
  align-items: center;
}

.hero-copy h1 {
  font-size: 44px;
}

.hero-copy .lede {
  max-width: 480px;
  margin-top: var(--space-4);
}

.hero-actions {
  display: flex;
  gap: var(--space-3);
  margin-top: var(--space-5);
}

.stats-overlap {
  position: relative;
  z-index: 1;
  margin-top: -56px;
import { test, expect } from '@playwright/test';

// Each page against its approved screenshot, at every size in the config.
const PAGES = [
  ['home', '/'],
  ['products', '/products.html'],
  ['pricing', '/pricing.html'],
  ['orders', '/orders.html'],
  ['contact', '/contact.html'],
  ['about', '/about.html'],
];

for (const [name, url] of PAGES) {
  test(name, async ({ page }) => {
    await page.goto(url);
    await expect(page).toHaveScreenshot(`${name}.png`, { fullPage: true });
  });
}
import { defineConfig, devices } from '@playwright/test';

const port = Number(process.env.PORT ?? 4173);

export default defineConfig({
  testDir: './tests',
  fullyParallel: false,
  workers: 1,
  retries: 0,
  reporter: 'list',
  use: { baseURL: `http://127.0.0.1:${port}` },
  projects: [
    { name: 'functional', testMatch: 'functional.spec.ts', use: { ...devices['Desktop Chrome'] } },
    { name: 'desktop', testMatch: 'visual.spec.ts', use: { browserName: 'chromium', viewport: { width: 1280, height: 800 }, deviceScaleFactor: 1 } },
    { name: 'phone', testMatch: 'visual.spec.ts', use: { browserName: 'chromium', viewport: { width: 390, height: 844 }, deviceScaleFactor: 1 } },
  ],
  webServer: {
    command: 'node server.js',
    url: `http://127.0.0.1:${port}`,
    reuseExistingServer: false,
    env: { PORT: String(port) },
    timeout: 30_000,
  },
});

